1	export type Cell = [number, number];
2	
3	// --- Neighbourhood topology: which cells are adjacent on the unbounded grid ---
4	
5	function isNeighbour([x, y]: Cell, [otherX, otherY]: Cell): boolean {
6	  const sameCell = x === otherX && y === otherY;
7	  return !sameCell && Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1;
8	}
9	
10	function livingNeighbourCount(cell: Cell, livingCells: Cell[]): number {
11	  return livingCells.filter((other) => isNeighbour(cell, other)).length;
12	}
13	
14	// --- Vitality policy: how a living neighbour count decides life ---
15	
16	const MIN_NEIGHBOURS_TO_SURVIVE = 2;
17	const MAX_NEIGHBOURS_TO_SURVIVE = 3;
18	
19	function survivesWith(livingNeighbours: number): boolean {
20	  return (
21	    livingNeighbours >= MIN_NEIGHBOURS_TO_SURVIVE &&
22	    livingNeighbours <= MAX_NEIGHBOURS_TO_SURVIVE
23	  );
24	}
25	
26	// --- Generation orchestration ---
27	
28	export function nextGeneration(livingCells: Cell[]): Cell[] {
29	  return livingCells.filter((cell) => survivesWith(livingNeighbourCount(cell, livingCells)));
30	}
